import React, { useState } from "react";
import "./JobForm.css";

const JobForm = ({ fetchJobs }) => {
  const [formData, setFormData] = useState({
    company: "",
    role: "",
    status: "Applied",
    date: "",
    link: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const apiUrl = process.env.REACT_APP_API_URL || "http://localhost:5000";

    try {
      const res = await fetch(`${apiUrl}/api/jobs`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to add job");
      }

      setFormData({
        company: "",
        role: "",
        status: "Applied",
        date: "",
        link: "",
      });

      fetchJobs(); // refresh the list
    } catch (err) {
      alert("Error adding job: " + err.message);
    }
  };

  return (
    <form className="job-form" onSubmit={handleSubmit}>
      <input name="company" value={formData.company} onChange={handleChange} placeholder="Company" required />
      <input name="role" value={formData.role} onChange={handleChange} placeholder="Role" required />
      <select name="status" value={formData.status} onChange={handleChange}>
        <option>Applied</option>
        <option>Interview</option>
        <option>Offer</option>
        <option>Rejected</option>
      </select>
      <input name="date" type="date" value={formData.date} onChange={handleChange} required />
      <input name="link" value={formData.link} onChange={handleChange} placeholder="Job Link" required />
      <button type="submit">Add Job</button>
    </form>
  );
};

export default JobForm;
